  border-radius: 8px;
  background: var(--back);
  color: var(--text);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
  transition: border-color 120ms ease;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.card:hover {
  border-color: var(--text);
}
.card.revealed,
.card.matched {
